        mv.visitMethodInsn(INVOKESTATIC,
                NamingCzar.internalFortressIntLiteral, NamingCzar.make,
                Naming.makeMethodDesc(NamingCzar.descString,
                                          NamingCzar.descFortressIntLiteral));
    }
}

